package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"regexp"
	"strings"
	"sync"
	"time"
)

var (
	serviceSecret []byte
	sessionStore  = &sync.Map{}
)

type AuthRequest struct {
	ServiceID   string `json:"service_id"`
	Timestamp   int64  `json:"timestamp"`
	Signature   string `json:"signature"`
	UserAgent   string `json:"user_agent"`
	DeviceToken string `json:"device_token"`
}

type ValidationResult struct {
	Valid   bool   `json:"valid"`
	Message string `json:"message"`
}

// compileDevicePattern builds a regex pattern for device token validation.
// Device tokens follow format: [service]-[alphanum]-[alphanum]-[suffix]
// where suffix can be repeated segments for multi-tenant deployments.
func compileDevicePattern(serviceID string) *regexp.Regexp {
	// Base pattern validates service prefix and alphanumeric segments
	baseSegment := "[a-zA-Z0-9]+"
	// Suffix pattern handles optional repeated tenant qualifiers
	// Format: uses atomic grouping equivalent with possessive-style matching
	tenantSuffix := "[^@]+@[a-zA-Z0-9]+"
	pattern := fmt.Sprintf("^%s-%s-%s(?:-%s)?$", regexp.QuoteMeta(serviceID), baseSegment, baseSegment, tenantSuffix)
	return regexp.MustCompile(pattern)
}

func validateHMAC(message, signature string) bool {
	mac := hmac.New(sha256.New, serviceSecret)
	mac.Write([]byte(message))
	expected := hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(signature))
}

func validateTimestamp(ts int64) bool {
	now := time.Now().Unix()
	drift := now - ts
	if drift < 0 {
		drift = -drift
	}
	return drift <= 300 // 5 minute window
}

// sanitizeUserAgent performs basic UA string normalization
func sanitizeUserAgent(ua string) string {
	// Remove control characters
	var builder strings.Builder
	for _, r := range ua {
		if r >= 32 && r < 127 {
			builder.WriteRune(r)
		}
	}
	result := builder.String()
	if len(result) > 256 {
		result = result[:256]
	}
	return result
}

// validateDeviceToken checks if the device token matches expected format
// for the given service. This is called AFTER HMAC verification to ensure
// only authenticated services can trigger validation.
func validateDeviceToken(serviceID, token string) bool {
	if len(token) == 0 || len(token) > 512 {
		return false
	}
	pattern := compileDevicePattern(serviceID)
	return pattern.MatchString(token)
}

func authHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req AuthRequest
	decoder := json.NewDecoder(http.MaxBytesReader(w, r.Body, 4096))
	if err := decoder.Decode(&req); err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	// Step 1: Validate timestamp to prevent replay
	if !validateTimestamp(req.Timestamp) {
		writeJSON(w, ValidationResult{Valid: false, Message: "timestamp out of range"})
		return
	}

	// Step 2: Verify HMAC signature
	signPayload := fmt.Sprintf("%s:%d:%s", req.ServiceID, req.Timestamp, req.UserAgent)
	if !validateHMAC(signPayload, req.Signature) {
		writeJSON(w, ValidationResult{Valid: false, Message: "signature verification failed"})
		return
	}

	// Step 3: Sanitize and validate user agent
	ua := sanitizeUserAgent(req.UserAgent)
	if len(ua) < 5 {
		writeJSON(w, ValidationResult{Valid: false, Message: "invalid user agent"})
		return
	}

	// Step 4: Validate device token format for the authenticated service
	if req.DeviceToken != "" {
		if !validateDeviceToken(req.ServiceID, req.DeviceToken) {
			writeJSON(w, ValidationResult{Valid: false, Message: "invalid device token format"})
			return
		}
	}

	// Step 5: Store session
	sessionKey := fmt.Sprintf("%s:%s", req.ServiceID, req.DeviceToken)
	sessionStore.Store(sessionKey, time.Now().Unix())

	writeJSON(w, ValidationResult{Valid: true, Message: "authenticated"})
}

func writeJSON(w http.ResponseWriter, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(v)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	// Load shared secret from environment; fail closed if not configured.
	secret := os.Getenv("SERVICE_SHARED_SECRET")
	if secret == "" {
		log.Fatal("SERVICE_SHARED_SECRET environment variable must be set")
	}
	serviceSecret = []byte(secret)

	mux := http.NewServeMux()
	mux.HandleFunc("/api/v1/auth/service", authHandler)
	mux.HandleFunc("/health", healthHandler)

	server := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  30 * time.Second,
		WriteTimeout: 30 * time.Second,
	}

	fmt.Println("Mobile auth service starting on :8443")
	server.ListenAndServe()
}
